import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))
    t = int(data[1 + n])
    lo, hi = 0, n - 1
    found = False
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == t:
            found = True
            break
        if a[lo] == a[mid] == a[hi]:
            lo += 1
            hi -= 1
        elif a[lo] <= a[mid]:
            if a[lo] <= t < a[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if a[mid] < t <= a[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    print('true' if found else 'false')

